-- Run this once in a Snowsight SQL worksheet (role ACCOUNTADMIN). Creates a service login
-- for the migration prototype, authenticated with a key pair (no password).
USE ROLE ACCOUNTADMIN;
CREATE USER IF NOT EXISTS P3_MIGRATOR
  TYPE = SERVICE
  DEFAULT_ROLE = ACCOUNTADMIN
  DEFAULT_WAREHOUSE = COMPUTE_WH
  RSA_PUBLIC_KEY = '';
GRANT ROLE ACCOUNTADMIN TO USER P3_MIGRATOR;
CREATE WAREHOUSE IF NOT EXISTS COMPUTE_WH WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE;
CREATE DATABASE IF NOT EXISTS MIGRATION_EVAL;
SELECT 'P3_MIGRATOR ready' AS status;
